-- Desliga o paralelismo automatico do Autonomous DB para esta sessao.
-- Sem isso, muitos MERGE seguidos na mesma tabela geram o erro ORA-12839
-- ("cannot modify an object in parallel after modifying it").
ALTER SESSION DISABLE PARALLEL DML;
ALTER SESSION DISABLE PARALLEL QUERY;

-- ============================================================
-- 02a. POPULAR TB_MUNICIPIO (todos os 645 municipios de SP, nao so os da coorte)
-- Usa MERGE para nao duplicar os municipios que voces ja inseriram manualmente.
-- ============================================================

-- Sentinela para pacientes diagnosticados fora de SP (0,38% da coorte, 174 de 45.416
-- casos). Sem isso, esses casos nao poderiam ser carregados, porque TB_MUNICIPIO
-- exige um DRS, e DRS so existe para Sao Paulo neste schema.
MERGE INTO TB_DRS tgt
USING (SELECT 'DRS-00' AS COD_DRS, 'Fora do Estado de SP' AS NOME_DRS FROM dual) src
ON (tgt.COD_DRS = src.COD_DRS)
WHEN NOT MATCHED THEN INSERT (COD_DRS, NOME_DRS) VALUES (src.COD_DRS, src.NOME_DRS);

MERGE INTO TB_MUNICIPIO tgt
USING (SELECT 'Fora do Estado de SP' AS NOME_MUNICIPIO, '000000' AS COD_IBGE, ID_DRS
       FROM TB_DRS WHERE COD_DRS = 'DRS-00') src
ON (tgt.NOME_MUNICIPIO = src.NOME_MUNICIPIO)
WHEN NOT MATCHED THEN INSERT (NOME_MUNICIPIO, COD_IBGE, ID_DRS)
VALUES (src.NOME_MUNICIPIO, src.COD_IBGE, src.ID_DRS);


